test(
  'arrow movement follows each board size, stops at edges and remembers one native tab stop',
  async ({ page }) => {
    await loadTimedBoard(page);
    const cards = page.locator('.card');
    for (const size of [4, 6, 8, 10, 12, 14, 16]) {
